/* cuopus phase 3: single-translation-unit include of the DEVICE-macro-ported
 * libopus 1.5.2 CELT decode path (device/gen/celt/**, regenerated by
 * device/port_silk.py -- do not edit gen/ by hand, edit the port script).
 *
 * Must be included AFTER cuopus_silk_all.cuh (shares the entropy decoder and
 * arch/fixed-point headers with the SILK TU half) and BEFORE cuopus_opus.cuh
 * (which needs celt_decode_with_ec, the CELTDecoder type and the typed ctl
 * helpers' field access).
 *
 * Notes:
 * - bands.c quant_partition is the explicit-frame-stack version (the vendor
 *   recursion is guarded under CUOPUS_QP_RECURSIVE, never defined): device
 *   threads must not recurse (phase-2 rule).
 * - celt_decoder.c's varargs opus_custom_decoder_ctl is compiled out under
 *   CUOPUS_CUDA; cuopus_celt_reset_state + the typed helpers in
 *   cuopus_opus.cuh replace the requests opus_decode_frame uses.
 * - modes.c pulls in static_modes_fixed.h: the big static mode tables
 *   (window, eBands, FFT twiddles/bitrev, PVQ cache) become __device__ const
 *   in GLOBAL memory (CUOPUS_DEVDATA), not __constant__ (too big).
 */
#ifndef CUOPUS_CELT_ALL_CUH
#define CUOPUS_CELT_ALL_CUH

#ifndef CUOPUS_SILK_ALL_CUH
#error "include cuopus_silk_all.cuh first"
#endif

#undef QA   /* silk NLSF2A.c leaves QA=16 defined; keep it out of celt */

/* Single-TU artifact: opus_custom.h only exposes the static-inline
 * opus_custom_decoder_get_size/_init prototypes when CELT_DECODER_C is
 * defined (each vendor TU defines it itself; here the header is first
 * included long before celt_decoder.c). */
#define CELT_DECODER_C

#include "gen/celt/mathops.c"
#include "gen/celt/laplace.c"
#include "gen/celt/cwrs.c"
#include "gen/celt/vq.c"
#include "gen/celt/pitch.c"
#include "gen/celt/celt_lpc.c"
#include "gen/celt/kiss_fft.c"
#include "gen/celt/mdct.c"
#include "gen/celt/modes.c"          /* + static_modes_fixed.h mode tables */
#include "gen/celt/quant_bands.c"
#include "gen/celt/rate.c"
#include "gen/celt/bands.c"
#include "gen/celt/celt.c"
#include "gen/celt/celt_decoder.c"

#endif /* CUOPUS_CELT_ALL_CUH */
